#!/usr/bin/env python3
from __future__ import annotations

import base64
import io
import lzma
import tarfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = """"""


def patch_publisher() -> None:
    path = ROOT / "scripts" / "publish_courses.py"
    text = path.read_text(encoding="utf-8")
    marker = '            "assessment_plan": assessment_plan(course),\n        }\n'
    replacement = (
        '            "assessment_plan": assessment_plan(course),\n'
        '            "study_method": course.get("study_method", []),\n'
        '            "diagnostic_assessment": course.get("diagnostic_assessment", {}),\n'
        '            "assessment_principles": course.get("assessment_principles", []),\n'
        '            "final_project": course.get("final_project", {}),\n'
        '            "core_resources": course.get("core_resources", []),\n'
        '        }\n'
    )
    if replacement not in text:
        if text.count(marker) != 1:
            raise RuntimeError("No se encontró el punto único para ampliar el publicador")
        path.write_text(text.replace(marker, replacement, 1), encoding="utf-8")


def main() -> int:
    raw = lzma.decompress(base64.b64decode(DATA))
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:") as archive:
        archive.extractall(ROOT, filter="data")
    patch_publisher()
    print("[ok] paquetes académicos extraídos y publicador ampliado")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
